import{_ as o,o as s,c as a,af as e}from"./chunks/framework.B28LkSoM.js";const h=JSON.parse('{"title":"数据分析概述与Jupyter","description":"数据分析的定义与流程、数据清洗的四个动作，以及 Jupyter Notebook 是什么、和普通 .py 文件的区别","frontmatter":{"title":"数据分析概述与Jupyter","published":"2026-09-20T00:00:00.000Z","description":"数据分析的定义与流程、数据清洗的四个动作，以及 Jupyter Notebook 是什么、和普通 .py 文件的区别","tags":["Python","数据分析"],"image":"https://img.tsh520.cn/file/blog/post-covers/python-51-data-analysis.webp","order":51,"date":"2026-09-20T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/Python学习笔记/51-数据分析概述与Jupyter.md","filePath":"posts/学习文档/Python学习笔记/51-数据分析概述与Jupyter.md"}'),r={name:"posts/学习文档/Python学习笔记/51-数据分析概述与Jupyter.md"};function d(n,t,l,i,p,u){return s(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1789862400000"},[...t[0]||(t[0]=[e('<h2 id="什么是数据分析" tabindex="-1">什么是数据分析 <a class="header-anchor" href="#什么是数据分析" aria-label="Permalink to &quot;什么是数据分析&quot;">​</a></h2><p>数据分析：从一堆看似杂乱的数据中，通过<strong>数据清洗、分析、可视化</strong>等手段，找出有价值的信息和结论，从而帮我们解决实际的问题。</p><p>常见场景：用户订单数据分析、电影榜单数据分析、学校学生成绩分析。</p><h3 id="分析流程" tabindex="-1">分析流程 <a class="header-anchor" href="#分析流程" aria-label="Permalink to &quot;分析流程&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数据收集 → 数据清洗处理 → 数据可视化 → 数据分析</span></span></code></pre></div><table tabindex="0"><thead><tr><th>环节</th><th>干什么</th><th>用什么</th></tr></thead><tbody><tr><td>数据收集</td><td>拿到原始数据（CSV、Excel、数据库、网络）</td><td>—</td></tr><tr><td>数据清洗处理</td><td>去除重复数据、处理缺失值、处理异常值、一致性检查</td><td><strong>Pandas</strong></td></tr><tr><td>数据可视化</td><td>把数据画成图，一图胜千言</td><td><strong>Matplotlib</strong></td></tr><tr><td>数据分析</td><td>从图和统计结果里得出结论</td><td>人的判断</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>数据分析里<strong>清洗往往是最花时间的一步</strong>——数据脏，后面的统计和图表都会跟着错。</p></div><h2 id="jupyter-notebook" tabindex="-1">Jupyter Notebook <a class="header-anchor" href="#jupyter-notebook" aria-label="Permalink to &quot;Jupyter Notebook&quot;">​</a></h2><p>Jupyter Notebook 是一个基于 Web 网页的、<strong>交互式</strong>的编程笔记本，让你可以把<strong>代码、运行结果、图表和笔记</strong>全部都放在一个文件里（在数据分析、机器学习、教学和科研等领域很常用）。</p><table tabindex="0"><thead><tr><th>对比</th><th>Python 文件（<code>.py</code>）</th><th>Jupyter 文件（<code>.ipynb</code>）</th></tr></thead><tbody><tr><td>运行方式</td><td>整个文件从头跑到尾</td><td>按<strong>单元格</strong>逐个运行，随时看结果</td></tr><tr><td>结果</td><td>打印到终端</td><td>直接显示在单元格下方（含表格、图表）</td></tr><tr><td>适合</td><td>写脚本、程序</td><td><strong>探索式分析</strong>：一边试一边看</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>用 PyCharm 第一次打开 <code>.ipynb</code> 时，会自动联网下载 Jupyter 相关软件包，等它装完即可。</p></div><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/python学习笔记/52-pandas入门与数据结构/">Pandas入门与数据结构</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li>数据分析：从杂乱数据中通过<strong>数据清洗</strong>、分析、<strong>可视化</strong>等手段，找出有价值的信息和结论</li><li>分析流程四步：数据收集 → <strong>数据清洗处理</strong> → <strong>数据可视化</strong> → 数据分析</li><li>数据清洗处理的四个动作：去除<strong>重复数据</strong>、处理<strong>缺失值</strong>、处理<strong>异常值</strong>、<strong>一致性</strong>检查</li><li>本课程里，清洗处理用 <strong>Pandas</strong> 库，数据可视化用 <strong>Matplotlib</strong> 库</li><li>Jupyter Notebook 是基于 <strong>Web 网页</strong>的、<strong>交互</strong>式的编程笔记本</li><li>Jupyter 文件（<code>.ipynb</code>）与 Python 文件最大的不同是：可以按<strong>单元格</strong>逐个运行</li></ol><h3 id="二、概念自测" tabindex="-1">二、概念自测 <a class="header-anchor" href="#二、概念自测" aria-label="Permalink to &quot;二、概念自测&quot;">​</a></h3><ul><li><p>[ ] <strong>2-1</strong> 为什么说&quot;清洗&quot;是数据分析里最花时间的一步？举一个脏数据会带坏结论的例子</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：从&quot;真实数据长什么样&quot;出发想：缺的、重的、错的、格式乱的都要人工判断怎么处理；例子挑一个能直接影响统计结果的毛病</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-1</strong> 因为真实数据总有缺失、重复、异常、格式不统一，必须先修好才能统计。例：单价里有负数（录入错误），直接算&quot;平均单价&quot;或&quot;销售金额合计&quot;就会被拉低，结论自然是错的。</p></details></li><li><p>[ ] <strong>2-2</strong> 什么情况下用 Jupyter 比用 <code>.py</code> 脚本更合适？举两个场景</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：想 Jupyter 的两大特点——&quot;按单元格随时看结果&quot;和&quot;代码/图表/文字放在一起&quot;，各对应一类场景</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-2</strong> ① 探索式分析：不知道数据长什么样，想一段一段试、边看结果边决定下一步；② 出报告/教学：代码、图表、文字说明放在一个文件里，别人打开就能看懂并复现。</p></details></li><li><p>[ ] <strong>2-3</strong> 拿到一份销售订单 CSV，你会按哪四步去清洗它？</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：按&quot;重复值 → 缺失值 → 异常值 → 格式一致性&quot;的顺序过一遍，每一步想一个针对订单数据的做法</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-3</strong> ① 去重（按订单号）；② 处理缺失值（删除或填充）；③ 处理异常值（如单价为负，取绝对值或删掉）；④ 一致性检查（日期格式 <code>2025/06/01</code> 统一成 <code>2025-06-01</code>）。</p></details></li></ul>',18)])])}const g=o(r,[["render",d]]);export{h as __pageData,g as default};
